cat << 'CSHARP' > analyze.cs
using Microsoft.Build.Logging.StructuredLogger;
using System;
using System.Collections.Generic;
using System.Linq;

var build = BinaryLog.ReadBuild("build.binlog");
var errors = build.FindChildrenRecursive<Error>();
var warnings = build.FindChildrenRecursive<Warning>();

Console.WriteLine($"=== BUILD ERRORS ({errors.Count}) ===\n");
foreach (var e in errors)
{
    var project = "";
    var node = e.Parent;
    while (node != null)
    {
        if (node is Project p) { project = p.Name; break; }
        node = node.Parent;
    }
    Console.WriteLine($"Project: {project}");
    Console.WriteLine($"File: {e.File}");
    Console.WriteLine($"Line: {e.LineNumber}");
    Console.WriteLine($"Code: {e.Code}");
    Console.WriteLine($"Message: {e.Text}");
    Console.WriteLine("---");
}

Console.WriteLine($"\n=== BUILD WARNINGS (showing first 30 of {warnings.Count}) ===\n");
foreach (var w in warnings.Take(30))
{
    var project = "";
    var node = w.Parent;
    while (node != null)
    {
        if (node is Project p) { project = p.Name; break; }
        node = node.Parent;
    }
    Console.WriteLine($"[{w.Code}] {project}: {w.Text}");
}
CSHARP
dotnet run --project analyze.csproj 2>&1 | head -200

