using Microsoft.Build.Logging.StructuredLogger;
using System;
using System.Linq;

var build = BinaryLog.ReadBuild("build.binlog");

// Find all projects and their results
var projects = build.FindChildrenRecursive<Project>();
Console.WriteLine("=== PROJECTS IN BUILD ===");
foreach (var p in projects)
{
    Console.WriteLine($"  {p.Name} - Succeeded: {p.Succeeded}");
}

// Look for package references in Services.csproj
Console.WriteLine("\n=== LOOKING FOR PACKAGE REFERENCES IN Services.csproj ===");
var svcProject = projects.FirstOrDefault(p => p.Name == "Services.csproj");
if (svcProject != null)
{
    var items = svcProject.FindChildrenRecursive<Item>();
    foreach (var item in items.Where(i => i.Parent is Folder f && f.Name.Contains("PackageReference")))
    {
        Console.WriteLine($"  PackageReference: {item.Name}");
    }

    // Also look at AddItem
    var addItems = svcProject.FindChildrenRecursive<AddItem>();
    foreach (var ai in addItems.Where(a => a.Name == "PackageReference"))
    {
        foreach (var child in ai.Children)
            Console.WriteLine($"  AddItem PackageReference: {child}");
    }
}

// Check source file content from messages
Console.WriteLine("\n=== SOURCE CONTEXT (messages mentioning UserService) ===");
var messages = build.FindChildrenRecursive<Message>();
foreach (var m in messages.Where(msg => msg.Text != null && msg.Text.Contains("UserService")).Take(10))
{
    Console.WriteLine($"  {m.Text}");
}
