using Microsoft.Build.Logging.StructuredLogger;
using System;
using System.Linq;

var build = BinaryLog.ReadBuild("build.binlog");

// Look for all Items to find PackageReference
Console.WriteLine("=== ALL AddItem NAMES ===");
var addItems = build.FindChildrenRecursive<AddItem>();
var names = addItems.Select(a => a.Name).Distinct().OrderBy(x => x);
foreach (var n in names)
    Console.WriteLine($"  {n}");

// Look for NamedNode or properties related to Newtonsoft or package
Console.WriteLine("\n=== SEARCHING ALL TEXT FOR 'Newtonsoft' ===");
var allNodes = build.FindChildrenRecursive<BaseNode>();
foreach (var node in allNodes.Where(n => n.ToString().Contains("Newtonsoft")).Take(20))
{
    Console.WriteLine($"  [{node.GetType().Name}] {node}");
}

// Get the csproj file content if embedded
Console.WriteLine("\n=== SEARCHING FOR Services.csproj CONTENT ===");
var msgs = build.FindChildrenRecursive<Message>();
foreach (var m in msgs.Where(msg => msg.Text != null && msg.Text.Contains("PackageReference")).Take(20))
{
    Console.WriteLine($"  {m.Text.Substring(0, Math.Min(200, m.Text.Length))}");
}

// Look at the source files from compilation
Console.WriteLine("\n=== SOURCE FILE: UserService.cs lines (from Compiler items) ===");
var items = build.FindChildrenRecursive<Item>();
foreach (var item in items.Where(i => i.Name != null && i.Name.Contains("UserService")).Take(5))
{
    Console.WriteLine($"  {item.Name} (parent: {item.Parent})");
}
CSHARP
