foreach (var sf in sourceFiles)
{
    Console.WriteLine($"  {sf.Name} ({sf.SourceFilePath})");
}

// Try EmbedInBinlog items
Console.WriteLine("\n=== EmbedInBinlog ITEMS ===");
var addItems = build.FindChildrenRecursive<AddItem>();
foreach (var ai in addItems.Where(a => a.Name == "EmbedInBinlog"))
{
    foreach (var child in ai.Children)
        Console.WriteLine($"  {child}");
}

// Check for restore messages
Console.WriteLine("\n=== RESTORE-RELATED MESSAGES ===");
var msgs = build.FindChildrenRecursive<Message>();
foreach (var m in msgs.Where(msg => msg.Text != null && (msg.Text.Contains("NU1") || msg.Text.Contains("restore") || msg.Text.Contains("Restore"))).Take(20))
{
    Console.WriteLine($"  {m.Text.Substring(0, Math.Min(300, m.Text.Length))}");
}

// Look at Reference items for Services project
Console.WriteLine("\n=== REFERENCES FOR Services.csproj ===");
var svcProjects = build.FindChildrenRecursive<Project>().Where(p => p.Name == "Services.csproj");
foreach (var proj in svcProjects.Take(1))
{
    var refs = proj.FindChildrenRecursive<AddItem>().Where(a => a.Name == "Reference" || a.Name == "PackageReference");
    foreach (var r in refs)
    {
        Console.WriteLine($"  [{r.Name}]");
        foreach (var child in r.Children)
            Console.WriteLine($"    {child}");
    }
}
