using Microsoft.Build.Logging.StructuredLogger;
using System;
using System.IO;
using System.Linq;

var build = BinaryLog.ReadBuild("build.binlog");

// The binlog embeds files - let's access them through the archive
// Try reading the binlog as archive to get embedded content
var reader = new BinLogReader();
var records = reader.ReadRecords("build.binlog").ToList();

Console.WriteLine($"Total records: {records.Count}");

// Look for embedded files
int embeddedCount = 0;
foreach (var record in records)
{
    if (record.Args is Microsoft.Build.Framework.BuildMessageEventArgs msg && msg.Message != null && msg.Message.Contains("project.assets.json"))
    {
        // skip
    }

    // Check for ProjectEvaluationStarted which may have project file content
    if (record.Args is Microsoft.Build.Framework.ProjectStartedEventArgs pse)
    {
        if (pse.ProjectFile != null && pse.ProjectFile.Contains("Services"))
        {
            Console.WriteLine($"\nProject started: {pse.ProjectFile}");
            if (pse.Properties != null)
            {
                var props = pse.Properties as System.Collections.IEnumerable;
                if (props != null)
                {
                    foreach (System.Collections.DictionaryEntry prop in props)
                    {
                        var key = prop.Key?.ToString() ?? "";
                        if (key.Contains("PackageReference") || key.Contains("Newtonsoft") || key == "RestorePackagesPath")
                        {
                            Console.WriteLine($"  {key} = {prop.Value}");
                        }
                    }
                }
            }
        }
    }
}

// Now get the embedded project.assets.json for Services
Console.WriteLine("\n=== Looking for embedded content ===");
var archives = build.FindChildrenRecursive<ArchiveFile>();
Console.WriteLine($"Found {archives.Count} archive files");
foreach (var a in archives.Take(20))
{
    Console.WriteLine($"  Archive: {a.Name} (children: {a.Children.Count})");
}
